286	    /** Fixed city-to-region table used to derive an owner's locality. */
287	    private static final Map<String, String> CITY_REGION = Map.of(
288	        "Sydney", "NSW",
289	        "Melbourne", "VIC",
290	        "Brisbane", "QLD");
291	
292	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
293	    public static final String UNKNOWN_REGION = "UNKNOWN";
294	
295	    /**
296	     * The canonical region for a city, derived from the fixed city-to-region table
297	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
298	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
299	     * source of the city-to-region mapping, shared by every rule that is keyed by
300	     * region so the mapping is never re-derived elsewhere.
301	     */
302	    public static String regionOf(String city) {
303	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
304	    }
305	
306	    /**
307	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
308	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
309	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
310	     * known region). Locality is read from the region-and-hash identity so it never re-derives
311	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
312	     */
313	    public String getLocality() {
314	        if (this.customerCode == null) {
315	            return UNKNOWN_REGION;
316	        }
317	        int dash = this.customerCode.indexOf('-');
318	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
319	    }
