119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	
121	        HttpStatus invalid = normalizeAndValidate(owner);
122	        if (invalid != null) {
123	            return new ResponseEntity<>(invalid);
124	        }
125	        if (isDailyLimitReached(owner.getRegistrationDate())) {
126	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
127	        }
128	
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        assignHousehold(owner);
131	
132	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
133	        if (conflict != null) {
