145	    /**
146	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
147	     * rejected. The owner's address is normalized (a blank address is rejected), its telephone is
148	     * converted to E.164 (an unconvertible number is rejected), its postcode is checked against its
149	     * city's region, a registration date in the future is rejected, and the effective registration
150	     * date (the supplied one, or today when none was given) is rolled onto a business day and stored
151	     * back on the owner. Returns {@code null} once the owner is valid and normalized, or the
152	     * {@link HttpStatus} the create must fail with ({@code 400 Bad Request}) otherwise.
153	     */
154	    private HttpStatus normalizeAndValidate(Owner owner) {
155	        String address = addressNormalizer.normalize(owner.getAddress());
156	        if (address.isEmpty()) {
157	            return HttpStatus.BAD_REQUEST;
158	        }
159	        owner.setAddress(address);
160	        String telephone = toE164(owner.getTelephone());
161	        if (telephone == null) {
162	            return HttpStatus.BAD_REQUEST;
163	        }
164	        owner.setTelephone(telephone);
165	        if (isDisposableEmail(owner.getEmail())) {
166	            return HttpStatus.BAD_REQUEST;
167	        }
168	        if (!owner.isPostcodeValid()) {
169	            return HttpStatus.BAD_REQUEST;
170	        }
171	        if (owner.getRegistrationDate() != null
172	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
173	            return HttpStatus.BAD_REQUEST;
174	        }
175	        LocalDate effectiveDate = owner.getRegistrationDate() != null
176	            ? owner.getRegistrationDate() : LocalDate.now();
177	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
178	        return null;
179	    }
180	
181	    /**
182	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
183	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
184	     */
185	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
186	        "mailinator.com", "tempmail.com", "guerrillamail.com");
187	
188	    /**
189	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
190	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
191	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
192	     * against the blocklist.
193	     */
194	    private boolean isDisposableEmail(String email) {
195	        if (email == null || email.isEmpty()) {
196	            return false;
197	        }
198	        int at = email.lastIndexOf('@');
199	        if (at < 0) {
200	            return false;
201	        }
202	        String domain = email.substring(at + 1).toLowerCase();
203	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
204	    }
205	
206	    /**
207	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
208	     * deterministically from the owner's lastName and postcode, so every owner sharing that
209	     * lastName and postcode is assigned the same value automatically, independent of whether the
210	     * owner declares it shares a household. The link is assigned before the
211	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
212	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
213	     * size}.
214	     */
215	    private void assignHousehold(Owner owner) {
216	        owner.setHouseholdId(householdId(owner));
217	    }
218	
219	    /**
220	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
221	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
222	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
223	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
224	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
225	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
226	     * when the owner clashes with nothing and may be created.
227	     */
228	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
229	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
230	            return HttpStatus.CONFLICT;
231	        }
232	        if (isCityAtCapacity(owner.getCity())) {
233	            return HttpStatus.CONFLICT;
234	        }
235	        return null;
236	    }
