238	    /**
239	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
240	     * {@code Location} header pointing at {@code /api/owners/{id}}.
241	     */
242	    private ResponseEntity<OwnerDto> created(Owner owner) {
243	        HttpHeaders headers = new HttpHeaders();
244	        headers.setLocation(UriComponentsBuilder.newInstance()
245	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
246	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
247	    }
248	
249	    /**
250	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
251	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
252	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
253	     * householdSize}. Each is computed from the owner's own fields together with the owners already
254	     * present, so this runs after the owner has been validated and has passed the duplicate and
255	     * capacity checks, and immediately before it is persisted.
256	     */
257	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
258	        owner.setCustomerCode(customerCode(owner));
259	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
260	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
261	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
262	        assignPossibleDuplicate(owner, sharesHousehold);
263	    }
264	
265	    /**
266	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
267	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
268	     * so it is never flagged. Otherwise, because this runs after the hard
269	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
270	     * match; it is flagged only when it is a soft match of an existing owner as determined by
271	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
272	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
273	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
274	     */
275	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
276	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
277	        owner.setPossibleDuplicate(match != null);
278	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
279	    }
280	
281	    /**
282	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
283	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
284	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
285	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
286	     * postcode never matches.
287	     */
288	    private Owner findSoftDuplicate(Owner owner) {
289	        if (owner.getPostcode() == null) {
290	            return null;
291	        }
292	        String candidateLastName = normalizeName(owner.getLastName());
293	        return this.clinicService.findAllOwners().stream()
294	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
295	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
296	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
297	            .min(Comparator.comparingInt(Owner::getId))
298	            .orElse(null);
299	    }
300	
301	    /**
302	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
303	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
304	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
305	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
306	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
307	     * every value built from the customer code (the membership number and its check digit) and the
308	     * owner's locality are derived from it.
309	     *
310	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
311	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
312	     * unique, and the de-duplicated code is returned.
313	     */
314	    private String customerCode(Owner owner) {
315	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
316	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
317	        String base = region + "-" + hash8;
318	
319	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
320	            .map(Owner::getCustomerCode)
321	            .filter(Objects::nonNull)
322	            .collect(Collectors.toSet());
323	
324	        if (!existingCodes.contains(base)) {
325	            return base;
326	        }
327	        int n = 2;
328	        while (existingCodes.contains(base + "-" + n)) {
329	            n++;
330	        }
331	        return base + "-" + n;
332	    }
333	
334	    /**
335	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
336	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
337	     * (business-day) registration date of the owner being created, so owners are counted per
338	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
339	     */
340	    private boolean isDailyLimitReached(LocalDate day) {
341	        long count = this.clinicService.findAllOwners().stream()
342	            .filter(existing -> day.equals(existing.getRegistrationDate()))
343	            .count();
344	        return count >= 100;
345	    }
346	
347	    /**
348	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
349	     * more than 80 owners have already been created for the given business day. Counts the owners
350	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
351	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
352	     * warning.
353	     */
354	    private boolean isBulkSignup(LocalDate day) {
355	        long count = this.clinicService.findAllOwners().stream()
356	            .filter(existing -> day.equals(existing.getRegistrationDate()))
357	            .count();
358	        return count > 80;
359	    }
360	
361	    /**
362	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
363	     * advance it to the following Monday; a weekday is returned unchanged.
364	     */
365	    private LocalDate toBusinessDay(LocalDate date) {
366	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
367	            date = date.plusDays(1);
368	        }
369	        return date;
370	    }
371	
372	    /**
373	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
374	     * more owners. Cities are compared case-insensitively.
375	     */
376	    private boolean isCityAtCapacity(String city) {
377	        long count = this.clinicService.findAllOwners().stream()
378	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
379	            .count();
380	        return count >= 50;
381	    }
382	
383	    /**
384	     * The number of existing owners that already share the given firstName and lastName,
385	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
386	     * whitespace runs collapsed). Counted over the owners present before this create.
387	     */
388	    private int namesakeCount(String firstName, String lastName) {
389	        String candidateFirstName = normalizeName(firstName);
390	        String candidateLastName = normalizeName(lastName);
391	        return (int) this.clinicService.findAllOwners().stream()
392	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
393	                && normalizeName(existing.getLastName()).equals(candidateLastName))
394	            .count();
395	    }
396	
397	    /**
398	     * The number of members in this owner's household after this create: the count of existing
399	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
400	     * created. An owner with no household ({@code householdId == null}) is a household of one.
401	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
402	     * does not depend on the order in which household members were created.
403	     */
404	    private int householdSize(String householdId) {
405	        if (householdId == null) {
406	            return 1;
407	        }
408	        long existing = this.clinicService.findAllOwners().stream()
409	            .filter(other -> householdId.equals(other.getHouseholdId()))
410	            .count();
411	        return (int) existing + 1;
412	    }
413	
414	    /**
415	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
416	     * cannot form a valid E.164 number.
417	     *
418	     * <p>A leading '+' and country code are kept when present; otherwise country code
419	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
420	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
421	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
422	     * exactly the national-digit count that code requires (see
423	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
424	     */
425	    private String toE164(String telephone) {
426	        if (telephone == null) {
427	            return null;
428	        }
429	        boolean hasCountryCode = telephone.trim().startsWith("+");
430	        String digits = telephone.replaceAll("\\D", "");
431	        String e164;
432	        if (hasCountryCode) {
433	            e164 = digits;
434	        } else {
435	            if (digits.startsWith("0")) {
436	                digits = digits.substring(1);
437	            }
438	            e164 = "61" + digits;
439	        }
440	        if (e164.length() < 8 || e164.length() > 15) {
441	            return null;
442	        }
443	        if (!Owner.hasValidNationalLength(e164)) {
444	            return null;
445	        }
446	        return "+" + e164;
447	    }
448	
449	    /**
450	     * Whether the candidate owner belongs to a household that already exists, and so must be
451	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
452	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
453	     * and postcode), so any existing owner carrying the same householdId means this owner is a
454	     * second member of an already-registered household. Two owners sharing a lastName and postcode
455	     * are therefore the same household: the second is a household duplicate.
456	     */
457	    private boolean isHouseholdDuplicate(Owner owner) {
458	        String householdId = owner.getHouseholdId();
459	        if (householdId == null) {
460	            return false;
461	        }
462	        return this.clinicService.findAllOwners().stream()
463	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
464	    }
465	
466	    /**
467	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
468	     * to a single space and lower-case. A null value normalizes to the empty string.
469	     */
470	    private String normalizeName(String value) {
471	        if (value == null) {
472	            return "";
473	        }
474	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
475	    }
476	
477	    /**
478	     * A stable shared identifier for the household an owner belongs to, derived deterministically
479	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
480	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
481	     * assigned the same value regardless of the order in which they are created. Formatted as the
482	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
483	     * (an absent postcode contributes the empty string).
484	     */
485	    private String householdId(Owner owner) {
486	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
487	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
488	        return shaHexUpper(key).substring(0, 12);
489	    }
490	
491	    /**
492	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
493	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
494	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
495	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
496	     * {@link #customerCode} keeps the first 8).
497	     */
498	    private String shaHexUpper(String input) {
499	        try {
500	            byte[] digest = MessageDigest.getInstance("SHA-256")
501	                .digest(input.getBytes(StandardCharsets.UTF_8));
502	            StringBuilder sb = new StringBuilder(digest.length * 2);
503	            for (byte b : digest) {
504	                sb.append(String.format("%02x", b));
505	            }
506	            return sb.toString().toUpperCase();
507	        }
508	        catch (NoSuchAlgorithmException e) {
509	            throw new IllegalStateException("SHA-256 not available", e);
510	        }
511	    }
